#include "FileManager.h"
#include "BookStore.h"
#include <filesystem>
#include <fstream>
#include <sstream>
#include <vector>
#include <iostream>
FileManager::FileManager(std::string d):dataDirectory(std::move(d)){}
const std::string& FileManager::getDirectory()const{return dataDirectory;}
bool FileManager::save(const BookStore& s)const{try{std::filesystem::create_directories(dataDirectory);std::ofstream b(dataDirectory+"/books.txt"),c(dataDirectory+"/customers.txt"),v(dataDirectory+"/sales.txt");if(!b||!c||!v)return false;for(int i=0;i<s.bookCount;++i)b<<s.books[i].getId()<<'\t'<<s.books[i].getTitle()<<'\t'<<s.books[i].getAuthor()<<'\t'<<s.books[i].getPrice()<<'\t'<<s.books[i].getStock()<<'\n';for(int i=0;i<s.customerCount;++i)c<<s.customers[i].getId()<<'\t'<<s.customers[i].getName()<<'\t'<<s.customers[i].getPhone()<<'\n';for(int i=0;i<s.saleCount;++i)v<<s.sales[i].getId()<<'\t'<<s.sales[i].getBookId()<<'\t'<<s.sales[i].getCustomerId()<<'\t'<<s.sales[i].getQuantity()<<'\t'<<s.sales[i].getTotal()<<'\n';return bool(b)&&bool(c)&&bool(v);}catch(const std::exception&e){std::cerr<<"Save error: "<<e.what()<<'\n';return false;}}
bool FileManager::load(BookStore& s)const{try{if(!std::filesystem::exists(dataDirectory))return true;s.clearData();std::string line;{std::ifstream f(dataDirectory+"/books.txt");while(std::getline(f,line)){std::istringstream x(line);std::string id,t,a,p,st;if(std::getline(x,id,'\t')&&std::getline(x,t,'\t')&&std::getline(x,a,'\t')&&std::getline(x,p,'\t')&&std::getline(x,st,'\t')){try{s.addBook(Book(std::stoi(id),t,a,std::stod(p),std::stoi(st)));}catch(...){}}}}{std::ifstream f(dataDirectory+"/customers.txt");while(std::getline(f,line)){std::istringstream x(line);std::string id,n,p;if(std::getline(x,id,'\t')&&std::getline(x,n,'\t')&&std::getline(x,p,'\t')){try{s.addCustomer(Customer(std::stoi(id),n,p));}catch(...){}}}}{std::ifstream f(dataDirectory+"/sales.txt");while(std::getline(f,line)){std::istringstream x(line);std::string id,b,c,q,t;if(std::getline(x,id,'\t')&&std::getline(x,b,'\t')&&std::getline(x,c,'\t')&&std::getline(x,q,'\t')&&std::getline(x,t,'\t')){try{if(s.saleCount==s.saleCapacity)s.growSales();int sid=std::stoi(id);s.sales[s.saleCount++]=Sale(sid,std::stoi(b),std::stoi(c),std::stoi(q),std::stod(t));if(sid>=s.nextSaleId)s.nextSaleId=sid+1;}catch(...){}}}}return true;}catch(const std::exception&e){std::cerr<<"Load error: "<<e.what()<<'\n';return false;}}
